const es = new EventSource('/events');

// default messages (events with no explicit name)
es.onmessage = (e) => render(JSON.parse(e.data));

// a named event type
es.addEventListener('price', (e) => updatePrice(JSON.parse(e.data)));

es.onerror = () => {
  // no code needed here: the browser reconnects automatically
};

